ero\" class=\"position-relative  py-6\">\n\n   <!-- Background Image -->\n    <div class=\"bg-image position-absolute top-0 start-0 w-100 h-100\"></div>\n\n    \n  <div class=\"container\">\n    <div class=\"row align-items-center\">\n      \n      <!-- Text Content -->\n      <div class=\"col-lg-6 mb-5 mb-lg-0\">\n        <p class=\"mb-2 mb-md-4 hero-subhead\" style=\"translate: none; rotate: none; scale: none; opacity: 1; transform: translate(0px, 0px);\">Meet Your Tutor</p>\n        <h1 class=\"display-4 hero-head mb-3 mb-md-4\" style=\"translate: none; rotate: none; scale: none; opacity: 1; transform: translate(0px, 0px);\">SHILPI PHALSWAL</h1>\n        <p class=\"hero-subpara mb-4\" style=\"translate: none; rotate: none; scale: none; opacity: 1; transform: translate(0px, 0px);\">\n          Hi! I’m Richard, with over six years of tutoring experience. I’m passionate\n          about making learning fun and engaging. My goal is to create an adventurous\n          atmosphere through interactive activities and tailored lesson plans, inspiring\n          a love for learning in all my students.\n        </p>\n        <a href=\"#contact\" class=\"call-now-btn \" style=\"translate: none; rotate: none; scale: none; opacity: 1; transform: translate(0px, 0px);\">\n          <i class=\"bi bi-telephone me-2\"></i> Contact Me\n        </a>\n      </div>\n\n      <!-- Image Content -->\n      <div class=\"col-lg-6 position-relative text-center\">\n        <!-- Decorative BG Circle -->\n        <div class=\"circle-bg\" style=\"translate: none; rotate: none; scale: none; opacity: 1; transform: translate(-50%, -50%);\"></div>\n\n        <!-- Decorative SVGs -->\n        <img src=\"https://static.zigrow.com/private-tutor/assets/img/hero icon-a.png\" class=\"hero-deco deco-1\" alt=\"\" style=\"translate: none; rotate: none; scale: none; transform: translate3d(0px, 12.9138px, 0px); opacity: 1;\">\n        <img src=\"https://static.zigrow.com/private-tutor/assets/img/hero icon-a.png\" class=\"hero-deco deco-2\" alt=\"\" style=\"translate: none; rotate: none; scale: none; transform: translate3d(0px, 12.9138px, 0px); opacity: 1;\">\n        <img src=\"https://static.zigrow.com/private-tutor/assets/img/hero icon-a.png\" class=\"hero-deco deco-3\" alt=\"\" style=\"translate: none; rotate: none; scale: none; transform: translate3d(0px, 12.9138px, 0px); opacity: 1;\">\n\n        <!-- Tutor Image -->\n        <img src=\"https://static.zigrow.com/private-tutor/assets/img/hero.png\" class=\"img-fluid hero-img position-relative\" alt=\"Richard Smith\" style=\"translate: none; rotate: none; scale: none; opacity: 1; transform: translate(0px, 0px);\">\n      </div>\n\n    </div>\n  </div>\n</section>\n\n  <!-- Hero Section Ends Here -->\n\n  <!-- Why Choose Section -->\n  <section id=\"why-choose\" class=\"py-6\">\n    <div class=\"container\">\n      <div class=\"col-md-9 m-auto text-center mb-5\">\n        <h2 class=\"main-heading display-6 mb-md-2 mb-3\" style=\"translate: none; rotate: none; scale: none; opacity: 1; transform: translate(0px, 0px);\">Why Choose Personalized Tutoring?</h2>\n        <p class=\"main-subpara\" style=\"translate: none; rotate: none; scale: none; opacity: 1; transform: translate(0px, 0px);\">\n          Get tailored lessons, one-on-one support, and flexible scheduling to make learning easier and more effective.\n        </p>\n      </div>\n\n      <div class=\"row justify-content-center gy-4\">\n        <div class=\"col-md-4\">\n          <div class=\"why-choose__card text-center\">\n            <div class=\"why-choose__icon mb-3\" style=\"translate: none; rotate: none; scale: none; opacity: 1; transform: translate(0px, 0px);\">\n              <i class=\"bi bi-person-fill\"></i>\n            </div>\n            <h5 class=\"why-choose__card-title mb-3\" style=\"translate: none; rotate: none; scale: none; opacity: 1; transform: translate(0px, 0px);\">One-on-One Attention</h5>\n            <p class=\"why-choose__card-text\" styl